-- ============================================================
-- PROYECTOS PRINCIPALES + ESQUEMAS (diagramas SVG) + CONEXIONES
-- Kits Academia Lizardo Villamarin (fase 2)
-- ============================================================
-- Depende de 2026_kit_lizardo_villamarin.sql (kits, placas, materiales).
-- Idempotente: agrega UNIQUE constraints si no existen y usa
-- ON CONFLICT para poder correr este archivo mas de una vez.

-- Constraints de idempotencia (no existian en la migracion anterior)
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'kit_conexiones_unico') THEN
    ALTER TABLE kit_conexiones ADD CONSTRAINT kit_conexiones_unico UNIQUE (proyecto_id, componente, pin_componente);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'kit_esquemas_unico') THEN
    ALTER TABLE kit_esquemas ADD CONSTRAINT kit_esquemas_unico UNIQUE (proyecto_id, tipo, version);
  END IF;
END $$;

-- ============================================================
-- 1. KIT_PROYECTOS (proyecto principal de cada kit)
-- ============================================================
ON CONFLICT (kit_id, slug) DO UPDATE SET
  titulo = EXCLUDED.titulo, descripcion = EXCLUDED.descripcion, objetivos = EXCLUDED.objetivos, orden = EXCLUDED.orden;

-- ============================================================
-- 2. KIT_CONEXIONES (tabla de pines por proyecto)
-- ============================================================
ON CONFLICT (proyecto_id, componente, pin_componente) DO UPDATE SET
  pin_placa = EXCLUDED.pin_placa, nota = EXCLUDED.nota, orden = EXCLUDED.orden;

-- ============================================================
-- 3. KIT_ESQUEMAS (diagrama SVG embebido como texto)
-- ============================================================
ON CONFLICT (proyecto_id, tipo, version) DO UPDATE SET contenido = EXCLUDED.contenido;
