INSERT INTO kit_proyectos (kit_id, titulo, slug, tipo, descripcion, objetivos, orden) VALUES
  ('kit-lv-octavo-egb', 'Semáforo inteligente con paso peatonal', 'semaforo-inteligente', 'principal', 'Un semáforo de 3 luces que cambia en secuencia y se detiene en rojo cuando un peatón presiona el botón para cruzar, avisando con un sonido.', ARRAY['Controlar varias salidas digitales (LEDs) con una secuencia de tiempo usando digitalWrite y delay.', 'Usar un pulsador con INPUT_PULLUP para que un evento externo interrumpa la secuencia normal del programa.', 'Calcular y aplicar la resistencia limitadora de corriente correcta para no quemar un LED.', 'Dar retroalimentación sonora al usuario con un buzzer activo.'], 1),
  ('kit-lv-noveno-egb', 'Basurero inteligente con apertura automatica', 'basurero-inteligente', 'principal', 'La tapa del basurero se abre sola cuando detecta una mano o un objeto cerca, usando un sensor ultrasónico y un servomotor, con un sonido de confirmación.', ARRAY['Medir distancia con un sensor ultrasónico HC-SR04 e interpretar el resultado en centímetros.', 'Controlar la posición de un servomotor para abrir y cerrar una tapa.', 'Diseñar una condición (if) que active una acción solo cuando se cumple una regla de distancia.', 'Agregar retroalimentación sonora para confirmar una acción automática.'], 1),
  ('kit-lv-decimo-egb', 'Sistema de riego automatico para plantas', 'sistema-riego-automatico', 'principal', 'Un sensor mide la humedad de la tierra y enciende automáticamente una bomba de agua cuando la planta lo necesita, con un umbral ajustable y aviso sonoro.', ARRAY['Leer un sensor analógico de humedad del suelo y relacionar el valor con el estado real de la tierra.', 'Controlar un actuador de mayor corriente (bomba de agua) de forma segura usando un módulo relé.', 'Ajustar un umbral de activación en tiempo real con un potenciómetro.', 'Combinar varias entradas y salidas (sensor, pulsador, bomba, LEDs, buzzer) en un solo sistema automático.'], 1),
  ('kit-lv-primero-bach', 'Estacion meteorologica con monitoreo ambiental', 'estacion-meteorologica-iot', 'principal', 'Mide temperatura, humedad y luz ambiental, y clasifica las lecturas en normal o alerta usando tres LEDs indicadores.', ARRAY['Soldar correctamente los pines de una placa ESP32-C3 con supervisión docente.', 'Leer temperatura y humedad ambiental con un sensor digital (DHT11).', 'Usar un divisor de voltaje para leer un sensor resistivo (LDR) con un microcontrolador de 3.3V.', 'Clasificar lecturas ambientales en rangos (normal / alerta) y mostrarlo con LEDs.'], 1),
  ('kit-lv-segundo-bach', 'Control inteligente de dispositivos del hogar', 'domotica-inteligente', 'principal', 'Detecta movimiento y nivel de luz para encender automáticamente una carga de 110V (representada con un LED por seguridad) a través de un relé con optoacoplador.', ARRAY['Controlar una carga de 110V de forma segura mediante un relé con optoacoplador.', 'Detectar movimiento con un sensor PIR y accionar un dispositivo automáticamente.', 'Explicar por qué nunca se debe manipular 110V sin supervisión ni aislamiento adecuado.', 'Combinar un sensor de luz (LDR) con un sensor de presencia (PIR) para automatizar el encendido de una luz.'], 1),
  ('kit-lv-tercero-bach', 'Sistema inteligente de monitoreo y automatizacion', 'monitoreo-automatizacion-iot', 'principal', 'Integra temperatura, humedad, distancia y luz en un solo tablero mostrado en una pantalla LCD, con alertas visuales y sonoras.', ARRAY['Integrar múltiples sensores (temperatura, humedad, distancia, luz) en un solo sistema de monitoreo.', 'Mostrar información en tiempo real en una pantalla LCD mediante el protocolo I2C.', 'Explicar por qué se necesita un conversor de nivel lógico entre un ESP32 (3.3V) y un módulo de 5V.', 'Diseñar un sistema que combine varias entradas y salidas para una automatización completa.'], 1)
